// Round-bottom flask support ring with three legs
// Units: mm

// ---------- Ring ----------
ring_od        = 90;   // ring outer diameter
ring_id        = 74;   // ring inner diameter
ring_thick     = 6;    // ring thickness (Z)
ring_top_z     = 70;   // height of ring top face

// ---------- Legs ----------
leg_d          = 6;    // leg diameter
leg_count      = 3;    // number of legs
leg_circle_d   = 82;   // diameter of circle through leg axes
leg_start_ang  = 0;    // first leg on +X axis (degrees)
leg_overlap    = 0.5;  // leg extends into ring to fuse the union

// ---------- Misc ----------
eps            = 0.5;  // cutter overshoot past faces
$fn            = 128;  // curve resolution

ring_bot_z = ring_top_z - ring_thick;   // ring bottom face height

union() {
    // Ring (annulus)
    translate([0, 0, ring_bot_z])
        difference() {
            cylinder(d = ring_od, h = ring_thick);
            translate([0, 0, -eps])
                cylinder(d = ring_id, h = ring_thick + 2 * eps);
        }

    // Legs from bed to ring
    for (i = [0 : leg_count - 1])
        rotate([0, 0, leg_start_ang + i * 360 / leg_count])
            translate([leg_circle_d / 2, 0, 0])
                cylinder(d = leg_d, h = ring_bot_z + leg_overlap);
}
