// Round-bottom flask support ring on three legs
// Units: mm. Print orientation: legs stand on the bed (z = 0), ring on top.

// ---------------- Parameters ----------------
ring_od        = 80;    // ring outer diameter
ring_id        = 56;    // ring inner diameter (flask seat opening)
ring_thk       = 6;     // ring thickness (Z)
ring_top_z     = 50;    // height of ring top face above bed

leg_d          = 6;     // leg diameter
leg_count      = 3;     // number of legs
leg_circle_d   = 68;    // diameter of circle on which leg axes lie
leg_start_ang  = 0;     // first leg on +X axis (degrees)
leg_overlap    = 1;     // legs extend this far into the ring for a solid union

eps            = 0.5;   // cutter overshoot past faces

$fn = 128;              // smoothness of curved shapes

// ---------------- Derived ----------------
ring_bot_z = ring_top_z - ring_thk;   // ring bottom face height (44 mm)
leg_len    = ring_bot_z + leg_overlap; // legs run from bed into ring

// ---------------- Model ----------------
union() {
    // Flat annular ring
    translate([0, 0, ring_bot_z])
        difference() {
            cylinder(d = ring_od, h = ring_thk);
            translate([0, 0, -eps])
                cylinder(d = ring_id, h = ring_thk + 2 * eps);
        }

    // Three vertical round legs, 120 degrees apart
    for (i = [0 : leg_count - 1])
        rotate([0, 0, leg_start_ang + i * 360 / leg_count])
            translate([leg_circle_d / 2, 0, 0])
                cylinder(d = leg_d, h = leg_len, $fn = 64);
}
