```openscad
// Round-bottom flask support ring on three legs
// Print orientation: legs stand on the bed (z = 0), ring on top.

$fn = 96;

// ---- Ring ----
ring_od        = 70;    // ring outer diameter
ring_id        = 54;    // ring inner diameter
ring_thick     = 4;     // ring thickness (Z)
ring_top_z     = 50;    // height of ring top face
ring_bottom_z  = ring_top_z - ring_thick;  // = 46

// ---- Legs ----
leg_d          = 8;     // leg diameter
leg_count      = 3;     // number of legs
leg_circle_d   = 62;    // diameter of circle through leg axes
leg_start_ang  = 0;     // first leg on +X axis
leg_overlap    = 1;     // legs extend this far into the ring for a solid union

// ---- Cut clearance ----
eps            = 0.5;   // extra length on cutting shapes

module ring() {
    translate([0, 0, ring_bottom_z])
        difference() {
            cylinder(d = ring_od, h = ring_thick);
            translate([0, 0, -eps])
                cylinder(d = ring_id, h = ring_thick + 2 * eps);
        }
}

module legs() {
    for (i = [0 : leg_count - 1]) {
        a = leg_start_ang + i * 360 / leg_count;
        translate([leg_circle_d / 2 * cos(a), leg_circle_d / 2 * sin(a), 0])
            cylinder(d = leg_d, h = ring_bottom_z + leg_overlap);
    }
}

union() {
    ring();
    legs();
}
```

