// PCB spacer with counterbore for socket-head screw
// Print orientation: standing on bed, z = 0 to 15, centred on origin

$fn = 96;

// --- Dimensions (mm) ---
body_d     = 20;    // outer diameter of spacer
body_h     = 15;    // total height of spacer
hole_d     = 5.5;   // through-hole diameter (screw clearance)
cbore_d    = 10;    // counterbore diameter (screw head)
cbore_h    = 3;     // counterbore depth from top face (z = 12 to 15)
eps        = 0.5;   // cutter overshoot past faces

difference() {
    // Main body
    cylinder(d = body_d, h = body_h);

    // Through hole along axis
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = body_h + 2 * eps);

    // Counterbore from top face
    translate([0, 0, body_h - cbore_h])
        cylinder(d = cbore_d, h = cbore_h + eps);
}
```

