```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate flat on the bed, rail pointing up (+Z)

$fn = 64;              // curve resolution (no curved features, set per rules)

// ---------- Base plate ----------
plate_len   = 120;     // plate length along X (mm)
plate_wid   = 30;      // plate width along Y (mm)
plate_thk   = 6;       // plate thickness, z = 0..6 (mm)

// ---------- Dovetail rail ----------
rail_len    = plate_len; // rail runs full plate length (mm)
rail_w_bot  = 8;       // rail width where it meets the plate, z = 6 (mm)
rail_w_top  = 14;      // rail width at its top face, z = 14 (mm)
rail_top_z  = 14;      // absolute Z of rail top face (mm)
rail_h      = rail_top_z - plate_thk; // rail height above plate (mm)

overlap     = 0.01;    // small overlap so rail fuses into plate (mm)

// ---------- Model ----------
union() {
    // Base plate, centred in X and Y, z = 0..6
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail: trapezoid in YZ, extruded along X
    // rotate([90,0,90]) maps 2D x -> Y, 2D y -> Z, extrusion -> X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_w_bot/2, plate_thk - overlap],  // bottom left
                [ rail_w_bot/2, plate_thk - overlap],  // bottom right
                [ rail_w_top/2, rail_top_z],           // top right
                [-rail_w_top/2, rail_top_z]            // top left
            ]);
}
```

