// Sliding mount with dovetail rail
// Print orientation: base plate flat on bed, rail pointing up (+Z)

$fn = 64;

// ---------- Base plate ----------
plate_len   = 100;   // plate length along X
plate_wid   = 36;    // plate width along Y
plate_t     = 5;     // plate thickness (z = 0 .. 5)

// ---------- Dovetail rail ----------
rail_len      = plate_len; // rail runs full length of plate
rail_w_bottom = 10;  // rail width where it meets plate (z = plate_t)
rail_w_top    = 16;  // rail width at top face
rail_top_z    = 13;  // absolute Z of rail top face

// ---------- Misc ----------
overlap = 0.01;      // small overlap so rail fuses into plate

module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_t]);
}

module dovetail_rail() {
    // 2D profile drawn with (Y, Z) coordinates, then extruded along X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_w_bottom/2, plate_t - overlap],
                [ rail_w_bottom/2, plate_t - overlap],
                [ rail_w_bottom/2, plate_t],
                [ rail_w_top/2,    rail_top_z],
                [-rail_w_top/2,    rail_top_z],
                [-rail_w_bottom/2, plate_t]
            ]);
}

union() {
    base_plate();
    dovetail_rail();
}
