// Sliding mount: base plate with dovetail rail
// Print orientation: base plate flat on bed, rail pointing up (+Z)

$fn = 64;

// ---------------- Dimensions (mm) ----------------
base_len    = 60;   // base plate length (X)
base_wid    = 40;   // base plate width (Y)
base_t      = 4;    // base plate thickness (Z), z = 0..4

rail_len    = 60;   // rail length (X), full plate length
rail_bot_w  = 10;   // rail width where it meets the plate (z = 4)
rail_top_w  = 14;   // rail width at its top face (z = 9)
rail_top_z  = 9;    // z height of the rail top face
rail_h      = rail_top_z - base_t;  // rail height (5 mm)

embed       = 0.5;  // rail root sunk into plate for a solid union (hidden)

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-base_len/2, -base_wid/2, 0])
        cube([base_len, base_wid, base_t]);

    // Dovetail rail: trapezoid in YZ, extruded along X
    // rotate([90,0,90]) maps local X->Y, local Y->Z, extrusion Z->X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_bot_w/2, base_t - embed],  // root, buried in plate
                [ rail_bot_w/2, base_t - embed],
                [ rail_bot_w/2, base_t],          // 10 mm wide at z = 4
                [ rail_top_w/2, rail_top_z],      // 14 mm wide at z = 9
                [-rail_top_w/2, rail_top_z],
                [-rail_bot_w/2, base_t]
            ]);
}
