// Glass stirring rod rest - block with V-grooves
// Print orientation: flat bottom on bed, grooves facing up

// ---------- Dimensions ----------
block_len     = 120;   // block length along X
block_wid     = 30;    // block width along Y
block_ht      = 18;    // block height along Z

groove_count  = 6;     // number of V-grooves
groove_pitch  = 20;    // centre-to-centre spacing of grooves along X
groove_top_w  = 10;    // groove width at top surface
groove_depth  = 5;     // groove depth (90-degree V: depth = top_w / 2)

overcut       = 1;     // extra cutter extension past faces (avoids coplanar faces)

// ---------- Derived ----------
first_x = -(groove_count - 1) * groove_pitch / 2;  // X of first groove centre

// ---------- Groove cutter ----------
// V profile in the XZ plane, extruded along Y through the full width.
// The sides keep their 45-degree slope above the top face (overcut region),
// so the V stays at 90 degrees.
module v_groove_cutter() {
    half_top = groove_top_w / 2 + overcut;   // half width at z = block_ht + overcut
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * overcut, center = true)
            polygon(points = [
                [-half_top, block_ht + overcut],
                [ half_top, block_ht + overcut],
                [ 0,        block_ht - groove_depth]
            ]);
}

// ---------- Part ----------
difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves
    for (i = [0 : groove_count - 1])
        translate([first_x + i * groove_pitch, 0, 0])
            v_groove_cutter();
}
