// Glass stirring rod rest - rectangular block with 5 V-grooves along Y

// ---- Block dimensions ----
block_len   = 104;   // X length (mm)
block_wid   = 50;    // Y width (mm)
block_ht    = 15;    // Z height (mm)

// ---- Groove dimensions ----
groove_count = 5;    // number of V-grooves
groove_pitch = 20;   // centre-to-centre spacing along X (mm)
groove_top_w = 10;   // groove width at top surface (mm)
groove_depth = 5;    // groove depth (mm), 90-degree V
overcut      = 0.5;  // extension past cut faces to avoid coplanar faces (mm)

// For a 90-degree V, each side widens by 1 mm per 1 mm of height,
// so extending upward by 'overcut' widens each side by 'overcut'.

module v_groove(x0) {
    translate([0, block_wid/2 + overcut, 0])
        rotate([90, 0, 0])
            linear_extrude(height = block_wid + 2*overcut)
                polygon(points = [
                    [x0 - groove_top_w/2 - overcut, block_ht + overcut],
                    [x0 + groove_top_w/2 + overcut, block_ht + overcut],
                    [x0, block_ht - groove_depth]
                ]);
}

difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves, centred along X
    for (i = [0 : groove_count - 1])
        v_groove((i - (groove_count - 1)/2) * groove_pitch);
}
