block_wid   = 40;   // block width along Y (mm)
block_h     = 15;   // block height along Z (mm)

// ---------- Groove parameters ----------
groove_count   = 6;    // number of V-grooves
groove_pitch   = 15;   // centre-to-centre spacing along X (mm)
groove_top_w   = 8;    // groove width at top surface (mm)
groove_depth   = 4;    // groove depth (mm), 90-degree V (half-width = depth)

// ---------- Cutting overshoot ----------
eps_z = 1;   // extension of groove cutter above top face (mm)
eps_y = 1;   // extension of groove cutter past each side face (mm)

// Derived values
groove_half_top = groove_top_w / 2;               // 4 mm half-width at top
cut_half_ext    = groove_half_top + eps_z;        // keep 90 deg V when extended upward
first_x         = -(groove_count - 1) * groove_pitch / 2;  // centre grooves along X

// V-groove cutter: 2D V profile in XZ, extruded along Y
module v_groove() {
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * eps_y, center = true)
            polygon(points = [
                [0, block_h - groove_depth],          // apex (bottom of V)
                [ cut_half_ext, block_h + eps_z],     // upper right (above top face)
                [-cut_half_ext, block_h + eps_z]      // upper left (above top face)
            ]);
}

difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // Six V-grooves across the full width
    for (i = [0 : groove_count - 1])
        translate([first_x + i * groove_pitch, 0, 0])
            v_groove();
}
