// Captive hex-nut clamping block
// Print orientation: bottom face (with the nut pocket) on the bed at z = 0

// ---------------- Dimensions ----------------
block_x     = 24;    // block length in X
block_y     = 20;    // block width in Y
block_z     = 12;    // block height in Z

hole_d      = 3.4;   // through-hole diameter (vertical, centred)

hex_flats   = 5.6;   // hex pocket size across the flats
hex_depth   = 2.6;   // hex pocket depth, cut up from the bottom face

eps         = 0.5;   // overshoot so cutters pass through faces

hole_fn     = 64;    // facets for the round hole

// Circumradius of the hexagon (centre to corner) from the across-flats size
hex_r = hex_flats / (2 * cos(30));

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Vertical through-hole
    translate([0, 0, -eps])
        cylinder(h = block_z + 2 * eps, d = hole_d, $fn = hole_fn);

    // Hex nut pocket from the bottom face.
    // With $fn = 6 one corner sits on +X, so two flats lie parallel to the X axis.
    translate([0, 0, -eps])
        cylinder(h = hex_depth + eps, r = hex_r, $fn = 6);
}
