// Cross-shaped bottle stabiliser
// Flat plus-sign plate lying on the bed, centred on the origin.

// ---------------- Parameters ----------------
plate_t      = 5;     // plate thickness (Z)
arm_len      = 60;    // overall length of each bar (X and Y)
arm_w        = 12;    // width of each bar
hole_d       = 4.5;   // through-hole diameter (centre and arm ends)
hole_offset  = 24;    // distance of arm-end holes from origin
cut_ext      = 0.5;   // extension of cutters past faces
$fn          = 64;    // curve resolution

// ---------------- Model ----------------
difference() {
    // Plus-sign body
    union() {
        translate([-arm_len/2, -arm_w/2, 0])
            cube([arm_len, arm_w, plate_t]);
        translate([-arm_w/2, -arm_len/2, 0])
            cube([arm_w, arm_len, plate_t]);
    }

    // Centre hole
    translate([0, 0, -cut_ext])
        cylinder(d = hole_d, h = plate_t + 2*cut_ext, $fn = 64);

    // Four arm-end holes
    for (a = [0, 90, 180, 270])
        rotate([0, 0, a])
            translate([hole_offset, 0, -cut_ext])
                cylinder(d = hole_d, h = plate_t + 2*cut_ext, $fn = 64);
}
