            cylinder(h = plate_t + 2*eps, d = head_d);
            // Slot from centre to rounded end at x = slot_end_x
            hull() {
                cylinder(h = plate_t + 2*eps, d = slot_w);
                translate([slot_end_x, 0, 0])
                    cylinder(h = plate_t + 2*eps, d = slot_w);
            }
        }
}

difference() {
    translate([-plate_l/2, -plate_w/2, 0])
        cube([plate_l, plate_w, plate_t]);
    keyhole_cutter();
