// Stepped riser - 5 equal solid steps climbing in +X
// Positioned per user coordinates: x = 0..75, y = 0..20, z = 0 at bed

// ---- Parameters ----
n_steps     = 5;    // number of steps
step_len    = 15;   // length of each step along X (mm)
step_rise   = 10;   // height increase per step (mm)
riser_depth = 20;   // extrusion depth along Y (mm)

total_len = n_steps * step_len;   // 75 mm overall length

// ---- Model ----
// Each block i starts at x = i*step_len, runs to the far end (x = 75),
// and is (i+1)*step_rise tall. The blocks overlap in volume, which avoids
// coincident faces. Their union gives the solid staircase, which is solid
// down to the bed.
union() {
    for (i = [0 : n_steps - 1]) {
        translate([i * step_len, 0, 0])
            cube([total_len - i * step_len, riser_depth, (i + 1) * step_rise]);
    }
}
