profile_pts = concat(
    [[0, 0], [total_len, 0]],
    // Walk back from the top step to the first: two corners per step
    [ for (i = [n_steps - 1 : -1 : 0]) each [
        [(i + 1) * step_len, (i + 1) * step_rise],  // front-right corner of step tread
        [ i      * step_len, (i + 1) * step_rise]   // back-left corner of step tread
