module rounded_plate() {
    // Hull of four corner cylinders gives a rounded rectangle
    hull() {
        for (sx = [-1, 1], sy = [-1, 1]) {
            translate([sx * (plate_length / 2 - corner_radius),
                       sy * (plate_width  / 2 - corner_radius),
                       0])
                cylinder(r = corner_radius, h = plate_thick);
        }
    }
}

